MOD = 10**9 + 7

def count_valid_subsets(N, S):
    dp = [[0] * 3 for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        digit = int(S[i - 1])
        for j in range(3):
            dp[i][j] = dp[i - 1][j]
            dp[i][(j + digit) % 3] += dp[i - 1][j]
            dp[i][(j + digit) % 3] %= MOD

    return dp[N][0]

